insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('intervention', 'beginner', 'module', 'm01-a-well-that-makes-water', 1, 'The golden case file carries four labelled ratio histories. What do all four of them share?', '["A published lateDerivativeSlope on every one, which the flat history reports as 0.000000000 because a constant ratio has a derivative that never moves anywhere.", "n = 40 samples, t running from 10.000000 to 3000.000000 days, and a span of 2.477121255 log cycles.", "A mechanism named in the golden beside each series.", "The same opening ratio of 1.200000000 before the four forms diverge."]'::jsonb, 1, 'Same axes and same sampling, four different shapes. The golden publishes a lateDerivativeSlope for three of them and null for the flat one, and publishes no expected mechanism anywhere.'),
  ('intervention', 'beginner', 'module', 'm01-a-well-that-makes-water', 2, 'The published coning history ends at a ratio of 3.750000000 and the published displacement history ends at 150.000000000. What does that ranking establish?', '["That the displacement well is the stronger candidate, because a water-oil ratio of 150.000000000 is exactly where a shutoff squeeze earns its money back on a well.", "That the coning well is still too dry to diagnose, so the ratio floor of 0.1 short-circuits it before any slope is computed at all on that history.", "Nothing about which is worth a squeeze, since the drier of the two is the picture no squeeze will ever help.", "That both are treatable, the derivative being 1.000000000 on each."]'::jsonb, 2, 'Coning carries treatable = false because the cone re-forms above whatever is shut off, and the level was never what decided it. The gradient separates the shapes.'),
  ('intervention', 'beginner', 'module', 'm01-a-well-that-makes-water', 3, 'Handed the published power law of eleven points, what does logLogSlope return?', '["Slope 1.350000000000, intercept 1.308332819650, r2 1.000000000000, n = 11 and a span of 2.000000000 log cycles, and no mechanism and no confidence anywhere.", "A slope of 1.350000000000 and the mechanism that exponent implies, an exponent above 1.3 being a channelling shape.", "A slope, an r-squared and a confidence, with the count and the span withheld until a window is named.", "A slope of 1.350000000000 and an uncertainty band built from the scatter about the fitted line."]'::jsonb, 0, 'Five members, and not one of them is a mechanism or a confidence. The published Theil-Sen slope through the same points is 1.350000000000 and the engine differs from it by 0.0000e+0.'),
  ('intervention', 'beginner', 'module', 'm01-a-well-that-makes-water', 4, 'Which number produced anywhere in this module carries a physical unit?', '["The multiplier a stimulation returns, which becomes a rate in stock tank barrels a day once the drainage geometry has been supplied to it.", "The span, since it is counted in log cycles of producing time and therefore inherits the day from the axis it was measured along.", "The pseudo-steady-state group, which carries the foot in through the drainage radius and the wellbore radius entered into it.", "The start of the late window, in days."]'::jsonb, 3, 'Slopes, intercepts, fit qualities, spans, the group and the skin are all dimensionless, and a multiplier is a fold increase. The one dimensional number the module produces itself is the day the late window starts on.'),
  ('intervention', 'beginner', 'module', 'm01-a-well-that-makes-water', 5, 'What does the measurement print when it is handed fewer than three usable points?', '["That a slope needs at least three points that are both positive, and that a log-log plot has nothing to say about zero or negative values.", "That the history is too short for a Chan reading and six samples is the minimum.", "Nothing, since it returns a slope of 0.000000000 on whatever survived the filter.", "That the drainage and wellbore radii are needed, the larger being the drainage one."]'::jsonb, 0, 'Two points return ok = false with n = 2, and so do four points of which one y is negative and one is zero, because only two of the four survived the filter.'),
  ('intervention', 'beginner', 'module', 'm01-a-well-that-makes-water', 6, 'Six points go into the fit and two of them carry a negative y. What comes back?', '["ok = false, because a fit that has to discard a point refuses outright rather than reporting a reading taken on some subset of what it was handed in the call.", "ok = true with n = 4, a slope of 1.000000000, an r-squared of 1.000000000 and a span of 0.903089987, and nothing said about the removal at all.", "ok = true with n = 6 and a span of 1.505149978.", "ok = true with a warning field naming the two removed points."]'::jsonb, 1, 'The six points cover 1.505149978 log cycles and the fit reports 0.602059991 of a cycle less. Comparing the returned n against the length of your own array is the only way to see it.'),
  ('intervention', 'beginner', 'module', 'm01-a-well-that-makes-water', 7, 'A five sample history is handed to the classifier. What happens?', '["It is read normally, because three surviving points is the only count this module enforces anywhere, and five clears that comfortably.", "It returns mechanism displacement at confidence n/a, since a history that short cannot show a derivative accelerating away from its ratio.", "It returns a slope with the ambiguous flag raised, which is what the module does whenever a reading is thin rather than actually wrong.", "It is refused, ok = false, mechanism indeterminate, every fit field absent."]'::jsonb, 3, 'The words are that a Chan reading needs a history and not a handful of points, and that six producing samples is the bare minimum. It is the one place a count is checked before any arithmetic runs.'),
  ('intervention', 'beginner', 'module', 'm01-a-well-that-makes-water', 8, 'One function in the geometry group reports failure as an object with an ok flag. What do the other three do?', '["They share the one contract skinPiMultiplier uses, so a call site written against an ok flag is correct at every one of the four call sites in turn.", "They throw, which is why the module wraps every geometry call in a try and reports the failure as an indeterminate mechanism further downstream.", "They return a bare NaN for the same bad geometry, with Number.isFinite false and no message.", "They return zero, which prints downstream as an infinite index."]'::jsonb, 2, 'A caller who tests result.ok is right on skinPiMultiplier and is reading an undefined property on pssDenominator, minimumSkin and skinFromPiRatio. Only Number.isFinite separates an answer from a refusal there.'),
  ('intervention', 'beginner', 'module', 'm01-a-well-that-makes-water', 9, 'channellingSlope is 1.3 and ambiguousBand is 0.25. What band does that put on the derivative slope?', '["From 1.3 up to 1.550000, since a reading that falls below the threshold is displacement outright and cannot then be called doubtful by the same test.", "From 1.050000 to 1.550000, a width of 0.500000.", "From 1.050000 up to 1.3.", "From -0.1 to 1.3, the whole stretch between the two mechanism thresholds."]'::jsonb, 1, 'The band is the threshold plus and minus 0.25, so any reading inside a width of 0.500000 is flagged doubtful while still being handed a mechanism.'),
  ('intervention', 'beginner', 'module', 'm01-a-well-that-makes-water', 10, 'Why does one comparison against 1.3 have to carry the whole separation between displacement and channelling?', '["Because for any power-law history the ratio and its derivative have the same log-log slope, so nothing but steepness is left to tell the two pictures apart.", "Because the ratio and the derivative are fitted over different windows, which makes their two slopes incomparable.", "Because the derivative is the only column a production database exports.", "Because the fit quality is identical on the two published histories, which removes the other candidate separator."]'::jsonb, 0, 'The published channelling history is a t^m with m = 1.600000000 and publishes 1.600000000000; the displacement history is a t with m = 1.000000000 and publishes 1.000000000000. The exponent and the derivative slope are one number twice.'),
  ('intervention', 'beginner', 'module', 'm01-a-well-that-makes-water', 11, 'Which of the four mechanism entries carries treatable = true?', '["Channelling and coning, since both describe water arriving where it was not wanted and both leave perforations that a squeeze can be aimed at.", "Coning, because the answer to a cone is less drawdown, and reducing drawdown is still a treatment carried out on this well rather than elsewhere.", "Channelling and not determined, because a history that has not settled the question leaves a squeeze on the table rather than ruling one out.", "Channelling."]'::jsonb, 3, 'Water arriving through a path of its own is plumbing and plumbing can be sealed. Coning, displacement and not determined all carry treatable = false, and the flag is a field in a lookup table rather than a calculation.'),
  ('intervention', 'beginner', 'module', 'm01-a-well-that-makes-water', 12, 'What does the independent oracle actually check in this module?', '["Every exported function, the golden publishing four labelled histories and a slope for each of them to be scored against in turn by the checker.", "The classifier, by comparing the mechanism returned on each published history against the mechanism the golden names for that same history.", "The log-log slope by Theil-Sen and the skin uplift by a full radial Darcy rate in SI, and nothing else.", "The screening and the ranking, being the two calls a planner reads."]'::jsonb, 2, 'Two pure arithmetic functions by two genuinely independent routes. chanDiagnosis, screenTreatments, rankTreatments and skinFromPiRatio are asserted against nothing at all.'),
  ('intervention', 'beginner', 'module', 'm01-a-well-that-makes-water', 13, 'Every point in a column sits at the same producing time. What does the fit do?', '["It refuses, with the sentence that every point is at the same time so there is no slope to measure, and returns no number that could be mistaken for one.", "It returns a slope of 0.000000000 with an r-squared of 1.000000000, which is the guard for a column with no variation in it.", "It reports a vertical fit, which lands above the channelling threshold of 1.3 and comes back as channelling.", "It drops every duplicated time and fits the single point that is left, returning n = 1."]'::jsonb, 0, 'That is an explicit refusal rather than a number that looks like an answer, and it is one of the two sentences the measurement can print.'),
  ('intervention', 'beginner', 'module', 'm01-a-well-that-makes-water', 14, 'The mechanism table and the treatment table sit beside the five calculations. What do they contribute?', '["The thresholds a slope is compared against, since the mechanism table is where channellingSlope at 1.3 and coningSlope at -0.1 are both defined and given their values.", "A label, a treatable flag and a note for each mechanism, and what each treatment addresses, with no arithmetic whatever.", "The confidence attached to a reading, computed there from the fit quality.", "The ranking of the seven treatments, worked out inside the treatment table."]'::jsonb, 1, 'They are lookups. The thresholds live in the diagnosis defaults, and the mechanism, the confidence and the treatable flag are all downstream of one number crossing another.'),
  ('intervention', 'beginner', 'module', 'm01-a-well-that-makes-water', 15, 'The note attached to the not determined label ends by saying what?', '["That the reading should be run again at a different window fraction until one of the three firm pictures comes back in place of it.", "That the water is arriving as it does in a swept reservoir, so no intervention carried out on this well is going to change any of it.", "Do not spend money on a treatment chosen by guesswork.", "That six producing samples is the minimum."]'::jsonb, 2, 'The label carries treatable = false and its note names a decision. It is an answer rather than a failure to reach one.'),
  ('intervention', 'beginner', 'module', 'm02-the-straight-line', 1, 'What does logLogSlope do to the two columns before any line is fitted?', '["It fits a power law to the raw columns by nonlinear regression, which is how it recovers the published exponent of 1.350000000000 without any transform at all.", "It rescales both columns onto the reported span of 2.000000000 log cycles so that the slope comes back independent of the units they arrived in.", "It takes the natural log of both and fits one straight line to the pairs by ordinary least squares.", "It differentiates the y column first, so that the slope it returns is a Bourdet derivative slope."]'::jsonb, 2, 'Nothing else happens inside it. Over the eleven published points it returns slope 1.350000000000 and intercept 1.308332819650, and the transform is the whole of the method.'),
  ('intervention', 'beginner', 'module', 'm02-the-straight-line', 2, 'The eleven published power-law points are spaced unevenly in x, from 1.000000 to 100.000000. What does the fit do about that spacing?', '["Nothing, because ordinary least squares weights every surviving pair the same however the points are spread along the axis.", "It interpolates the pairs onto an even grid in ln x first, which is why the span comes back as exactly 2.000000000 log cycles rather than as an awkward number.", "It down-weights the crowded low end of the axis, which is what pins the intercept at 1.308332819650 rather than at the value of the first pair.", "It refuses, since an uneven x column has no single spacing to fit along."]'::jsonb, 0, 'The spacing is uneven on purpose and the fit is exact anyway, r2 1.000000000000 over all eleven points and a difference of 0.0000e+0 from the published slope.'),
  ('intervention', 'beginner', 'module', 'm02-the-straight-line', 3, 'The intercept a fit returns is the height of the fitted line at which point on the x axis?', '["At the first sample of the series, which on the published power law is x = 1.000000 with y = 3.700000000, so the two readings coincide there by construction.", "At the centroid of the fitted data, which is where an ordinary least squares line is pinned and which on eleven points spanning 2.000000000 log cycles sits well inside the range.", "At x = 0, which is why the intercept is the one member that moves with a change of time base.", "At x = 1.000000, where ln x is zero."]'::jsonb, 3, 'The published case puts a golden pair exactly there, x = 1.000000 with ln y = 1.308332820, and the fitted intercept over all eleven points is 1.308332819650.'),
  ('intervention', 'beginner', 'module', 'm02-the-straight-line', 4, 'The teaching well fitted whole returns an intercept of -6.052413433629. What water-oil ratio does the fitted line put at one day?', '["0.0032, the coefficient the history was built from, because a fit recovers the constant of a power law as exactly as it recovers the exponent of one.", "2.352178324e-3, which is the exponential of that intercept.", "0.048760749, since the first sample of the history is what the line is pinned through at the short end of the axis.", "-6.052413433629, the intercept being a ratio in the same units as the column it was fitted through."]'::jsonb, 1, 'A straight line in logs is y = a x^m, so the intercept is ln a. The line reads 2.352178324e-3 at one day, climbing as t to the power 1.098217467822, and the 0.0032 per day it was built from was never going to come back out of one straight line.'),
  ('intervention', 'beginner', 'module', 'm02-the-straight-line', 5, 'Which member of the return moves when the producing time column is recounted on a different base?', '["The intercept, since it is the log of the value at one on the x axis and that value moves with the base.", "The slope, because a gradient is measured along an axis whose spacing changes with whatever unit that axis is counted in.", "The span, which is counted in log cycles of producing time and therefore inherits the day from the axis it was measured along.", "The fit quality, which falls as the transform stretches the shorter of the two columns."]'::jsonb, 0, 'A log-log slope is d ln y / d ln x and carries no unit at all, which is why a slope can be compared against a threshold of 1.3 and an intercept cannot.'),
  ('intervention', 'beginner', 'module', 'm02-the-straight-line', 6, 'What makes the oracle''s agreement with the engine on the published power law a statement worth making?', '["The two routes read different windows of the same eleven points, so their agreement tests the choice of window as well as the arithmetic that follows it.", "The oracle fits the same least squares line in a second language, which removes any doubt about how the estimator itself was implemented.", "Theil-Sen is the median of every pairwise slope, so it shares no mean, no square and no covariance with least squares.", "The check is repeated on all four of the published labelled histories."]'::jsonb, 2, 'The engine returns 1.350000000000 and 1.308332819650 against those same published values, a difference of 0.0000e+0 on each. Agreement between two estimators with nothing in common is about arithmetic, and there is no well in that case at all.'),
  ('intervention', 'beginner', 'module', 'm02-the-straight-line', 7, 'The engine matches the published slope, the published intercept and a perfect fit on the power law, every difference 0.0000e+0. What does that licence?', '["A claim that a power law is the right model for a water-oil ratio history, since the estimator recovers one exactly whenever one is present in the column.", "A claim that any history returning an r-squared near 1.000000000000 has been read on the correct window, the published case being the reference for what a correct reading looks like.", "A claim that the published exponent of 1.350000000000 is above the channelling threshold and so describes a well with a water path.", "A claim about the arithmetic, and nothing whatever about a well."]'::jsonb, 3, 'There is no well in the power-law case at all. Eleven points, an exponent and two estimators, and the exactness is a property of the transform rather than of anything producing.'),
  ('intervention', 'beginner', 'module', 'm02-the-straight-line', 8, 'On the published channelling history the ratio slope and the derivative slope both come back at 1.600000000. Why are they the same number?', '["Because both fits were taken over the same 20 samples, and two least squares lines drawn through one window return one slope by construction.", "Differentiating a power law gives another power law with the same exponent, so the two lie on parallel lines in log space.", "That history''s derivative column was generated from the fitted ratio line rather than measured.", "Because the fit quality is 1.000000000 on both, and two exact fits cannot differ."]'::jsonb, 1, 'The published displacement history does the same thing at 1.000000000 twice. Nothing in the shape separates the two pictures, so a threshold of 1.3 has to.'),
  ('intervention', 'beginner', 'module', 'm02-the-straight-line', 9, 'Over the window starting at t = 186.345364 days the engine returns -0.539955222223 on the published coning history while the oracle publishes -0.555098339661. What produced a difference of 1.514312e-2 on a series with no noise in it?', '["The plateau form is not a power law, so a curved trend in log space is weighted differently by the two estimators and neither is measuring a slope that exists.", "Rounding in the engine''s accumulation of the sums of squares, which is about the size of error a float carries over 20 samples.", "The oracle reading a different stretch of the series, series[20:] against the shorter window the engine chose for itself on that history.", "Scatter in the coning derivative column, which the plateau form makes worst at the late end where the ratio has stopped climbing."]'::jsonb, 0, 'The fit quality over that window is 0.948751314445 and reads as a good fit throughout. Both routes answer their own question honestly, on data that has no scatter in it at all.'),
  ('intervention', 'beginner', 'module', 'm02-the-straight-line', 10, 'The teaching well fitted whole returns a ratio slope of 1.098217467822 and its eight most recent samples return 0.143809349. Which of the two is wrong?', '["The eight-sample reading, because half of those samples sit after the well was beaned back on day 2200 and no fit may be carried across an event like that.", "The whole-history reading, which is contaminated by the early life of the well from t = 15.000000 days, before any path for the water had formed.", "Neither, since the two answer different questions about the same 38 numbers.", "The whole-history reading, since this module reads late windows and nothing else."]'::jsonb, 2, 'Both come off one column. The return carries no field naming the window, so a slope is not a measurement until the window is written beside it.'),
  ('intervention', 'beginner', 'module', 'm02-the-straight-line', 11, 'Which window fraction on the teaching well returns the same ratio slope as fitting the raw history whole?', '["0.50, the shipped default, which is the window the fit is calibrated against and therefore the one that agrees with a whole-history reading.", "1.00, which takes in all 38 samples from t = 15.000000 days.", "0.90, which at 35 of the 38 samples is close enough that the two agree to the precision anybody quotes.", "None of them, the two being different calculations."]'::jsonb, 1, 'It returns 1.098217468 against the whole-history 1.098217467822, because at that fraction the window is the history.'),
  ('intervention', 'beginner', 'module', 'm02-the-straight-line', 12, 'At its default window the teaching well returns 1.040602176 and 1.442132492 side by side in one object. What separates the two numbers?', '["One is the ratio measured over the late window and the other is the same ratio measured over the whole 38 samples, so the pair is a before and after of the choice of window.", "One is a least squares slope and the other a Theil-Sen slope on the same points.", "One carries a unit and the other does not.", "One was fitted on 19 samples and the other on the 15 of them whose derivative is positive."]'::jsonb, 3, 'The gap is 0.401530316. The ratio fit covers 1.157940604 log cycles and the derivative fit 0.900620470, and nothing in the object says the two were measured on different data.'),
  ('intervention', 'beginner', 'module', 'm02-the-straight-line', 13, 'What is logLogSlope told about the two columns it receives?', '["Nothing at all: not which axis is time, not whether the y column is a ratio or a derivative, and not whether the rows are a whole history or a slice somebody chose.", "The name of the y column, which is what lets the ratio floor of 0.1 be applied to a water-oil ratio and withheld from a derivative.", "The window it was cut from, which travels in the return as the day the fit starts on.", "Which of the two columns is the dependent one, and nothing else."]'::jsonb, 0, 'It is arithmetic on two columns. A slope that comes out of it is therefore a property of a window, of one column, and of the points that survived, and the return names none of the three.'),
  ('intervention', 'beginner', 'module', 'm02-the-straight-line', 14, 'What turns a written slope of 1.442132492 into a measurement rather than a fragment?', '["Writing the fit quality beside it, which on that reading is 0.998513658 and settles how much the number is worth on its own.", "Writing the threshold beside it, since 1.442132492 against a channellingSlope of 1.3 is what the number is for.", "Naming the column, the count and the span beside it: derivative, 15 samples from t = 250.242976 days, 0.900620470 log cycles.", "Quoting it at full precision rather than rounded."]'::jsonb, 2, 'The fit quality describes the line and the threshold describes the decision. Neither says which points were read, and that is the part the return leaves out.'),
  ('intervention', 'beginner', 'module', 'm02-the-straight-line', 15, 'Across the whole range of the window dial the teaching well''s derivative slope moves by 0.370920348. What in the data moved to produce it?', '["The four samples with a negative derivative, entering and leaving as the window widens.", "Nothing, because every row of that sweep is the same 38 samples read through a different window.", "The peak of the history at a water-oil ratio of 14.587294415, which passes into the window part way down the sweep and drags the fitted line steeper.", "The sample count, which is the only member of the return that a window can change."]'::jsonb, 1, 'It runs from 1.229355999 on the whole history to 1.600276347 on the eight most recent samples, and at that steepest end the fit reports no span at all.'),
  ('intervention', 'beginner', 'module', 'm03-reading-the-fit', 1, 'What question does the fit quality returned beside a slope answer?', '["How likely the mechanism read off that slope is to be the one operating in the rock, which is why a value below 0.5 is refused as noise.", "How close the surviving points sit to the line that was drawn through them.", "How far the least squares slope sits from the Theil-Sen slope.", "How much of the well''s producing life the window covers."]'::jsonb, 1, 'It is a statement about the line and not about the well. Further down the module it becomes a gate, minR2 being 0.5, but the quantity itself never leaves the fit.'),
  ('intervention', 'beginner', 'module', 'm03-reading-the-fit', 2, 'The engine returns the fit quality as a fraction while its own refusal sentences speak of the same quantity in another form. What is the trap?', '["The sentences report it as a percentage, so a reading of 0.0 percent in a message and a value in the return object are the same number written two ways.", "The sentences report it as a residual sum of squares, so a small value in a message corresponds to a large value in the return object.", "The sentences report the Theil-Sen fit quality and the object the least squares one, which is why the two can differ by 1.514312e-2.", "The sentences round it to two decimals."]'::jsonb, 0, 'It is a fraction between zero and one in the return and a percentage in the text, so say which you mean every time you quote one.'),
  ('intervention', 'beginner', 'module', 'm03-reading-the-fit', 3, 'The published coning history returns a derivative fit quality of 0.948751314445 over the window starting at t = 186.345364 days. What does that number support?', '["That the falling slope of -0.539955222223 is reliable to about the second decimal, since the fit quality and the spread between estimators track each other closely.", "That the series carries very little noise, a plateau form being the smoothest of the four published shapes and the easiest of them to fit.", "That a straight line describes those points well, and nothing more.", "That the coning label attached to it is safe."]'::jsonb, 2, 'Over those same points the two independent routes give -0.539955222223 and -0.555098339661, a difference of 1.514312e-2 on a series with no noise in it. A curved trend in log space is fitted well by a line that is still not measuring anything.'),
  ('intervention', 'beginner', 'module', 'm03-reading-the-fit', 4, 'The published flat history sits at a ratio of 1.200000000 throughout, and its ratio fit over the late window returns a fit quality of 0.000000000. What does that reading mean?', '["The series is too noisy to carry a slope, which is the reading the module gives whenever the fit quality falls below the floor of 0.5 that it sets for itself.", "The fit failed and returned ok = false, since a column with no variation in it has no line that could be drawn through the points at all.", "The points are scattered about the fitted line by roughly the amount a random column would scatter, which is what a value that low is normally reporting.", "The fit explains none of a variation that does not exist."]'::jsonb, 3, 'Nothing is scattered anywhere in that series. A fit quality of 0.000000000 on a constant column prints the same value it would print for pure noise, which is why the number cannot be read on its own.'),
  ('intervention', 'beginner', 'module', 'm03-reading-the-fit', 5, 'The teaching well fitted whole returns a ratio slope of 1.098217467822 at a fit quality of 0.989832434458, on a history that peaks at 14.587294415 and falls back to 9.329979637. What does the fit quality know about the fall?', '["Nothing, since it reports only that the surviving points sit near a line.", "That the fall is small enough not to matter, a value that high being unreachable if a turning point of that size sat inside the fitted window.", "That the fall happened late, because the fit quality is weighted toward the recent end of the window on a log axis.", "That the fall is real rather than a meter error."]'::jsonb, 0, 'The well was beaned back on day 2200 and the fit quality of 0.989832434458 is untouched by it. Confidence in the line is not confidence in the answer.'),
  ('intervention', 'beginner', 'module', 'm03-reading-the-fit', 6, 'What does spanDecades count?', '["The number of samples the fit drew through, expressed on a log scale so that a long history and a short one can be compared against the floor of 0.4.", "The distance the surviving points cover along the log x axis, in log cycles.", "The producing days between the first and last sample, divided by ten.", "The orders of magnitude the y column climbs across the window."]'::jsonb, 1, 'It is the only member of the return that says how much ground the line was drawn across, and the published power law reports 2.000000000 for eleven points running from x = 1.000000 to 100.000000.'),
  ('intervention', 'beginner', 'module', 'm03-reading-the-fit', 7, 'On the published power law, how does the step from x = 1.000000 to 10.000000 compare with the step from 10.000000 to 100.000000?', '["The second is ten times the first, which is why least squares leans on the far end of the axis and the fitted slope follows the widest-spaced points.", "The second is the shorter of the two once the transform is applied, which is what puts six of the eleven published points at x of 10.000000 or less.", "They are the same distance, because on a log axis distance is multiplication.", "They cannot be compared, the axis being uneven."]'::jsonb, 2, 'Each is one log cycle of the 2.000000000 the case reports, and least squares weights every surviving pair the same in either of them.'),
  ('intervention', 'beginner', 'module', 'm03-reading-the-fit', 8, 'The teaching well reports a span of 2.380211242 on its ratio fitted whole and 2.122891107 on its derivative fitted whole, from the same 38 samples. What made them differ?', '["The derivative fit was taken over the late window while the ratio fit was taken over the whole history, which is the difference the two spans are reporting.", "The derivative column starts one sample later than the ratio column, since a derivative needs two points before it can report anything at all.", "The derivative fit reports its span after taking the log of the y column a second time, which compresses the axis it is measured along.", "Four samples with a negative derivative were dropped before the derivative fit."]'::jsonb, 3, 'A log axis has nothing to say about a negative number, so the fit removed those four and reported 2.122891107 on n = 34. That difference is the only visible trace of the removal.'),
  ('intervention', 'beginner', 'module', 'm03-reading-the-fit', 9, 'The four samples the teaching well''s derivative fit dropped run from 2308.407093 to 3600.000000 days. Why is that a small loss in log cycles and a large one on a calendar?', '["Because the samples are spaced geometrically, so a stretch that nearly doubles the record in days adds only a fraction of a cycle to the axis the fit is measured on.", "Because the span is computed before the drop and therefore never reflected those four samples in the first place.", "Because the axis is logarithmic in the ratio rather than in time, so the length of a stretch in days does not enter the span at all.", "Because the four sit outside the late window and spans are reported for the window only."]'::jsonb, 0, 'The ratio fit covers 2.380211242 log cycles and the derivative fit 2.122891107. A long-looking record can still be a short reading, which is why the span and the sample count answer different questions.'),
  ('intervention', 'beginner', 'module', 'm03-reading-the-fit', 10, 'A fit survives its point drop and returns a slope. What can still stop the reading being used?', '["Nothing, since a fit that returns ok = true has passed every check the module makes on a measurement before the mechanism is read off it.", "The span, which has a floor of 0.4 log cycles and is measured on what survived rather than on what was handed in.", "The intercept, which has to be finite before the slope beside it can be quoted.", "The sample count, which has a floor of 6 inside the fit itself."]'::jsonb, 1, 'The drop shortens the span as well as thinning the fit, so on a short enough window the removal is the difference between a reading and a refusal.'),
  ('intervention', 'beginner', 'module', 'm03-reading-the-fit', 11, 'The count a fit returns is the count of what?', '["The points handed in, which is why comparing it against the length of your own array is a check that can never fail and is therefore not worth making.", "The points inside the window, before the filter runs and before the fit is attempted on them.", "The points left after every y that is not strictly positive was removed.", "The points that lie within the fitted line''s residual band, the rest being treated as outliers and excluded."]'::jsonb, 2, 'The published power law returns n = 11 on 11 points handed in, while the teaching well''s derivative fit returns n = 34 on 38. Only the second of those tells you anything happened.'),
  ('intervention', 'beginner', 'module', 'm03-reading-the-fit', 12, 'Four points go into the fit, one with a negative y and one with a y of zero, and the fit refuses. What count does the refusal carry?', '["n = 4, the refusal reporting what it was handed rather than what it kept, which is the one place the module states the supplied count anywhere.", "n = 0, since a refusal returns no fit and therefore nothing that could be counted at either end of it.", "n = 3, the minimum the sentence names.", "n = 2, because only two of the four survived the filter."]'::jsonb, 3, 'The words are that a slope needs at least three points that are both positive. The count in a refusal is a count after the drop, exactly as it is in an answer.'),
  ('intervention', 'beginner', 'module', 'm03-reading-the-fit', 13, 'The published channelling and displacement histories both return a fit quality of 1.000000000 over the window starting at t = 186.345364 days, and one sends a squeeze to the well while the other refuses one. What separated them?', '["A slope of 1.600000000 against a slope of 1.000000000, compared to a threshold of 1.3 that was typed rather than measured.", "The fit quality, which is equal to the last digit on both and therefore leaves the sample count of 20 to carry the difference between them.", "The span, which at 1.206802663 log cycles clears the floor of 0.4 on one history and not on the other.", "The published Theil-Sen slopes, which differ from the engine''s by 2.220446e-16 on one and 4.440892e-16 on the other."]'::jsonb, 0, 'Two flawless fits and two opposite verdicts. Neither fit is better than the other, and the fit quality has no opinion about the comparison that produced the label.'),
  ('intervention', 'beginner', 'module', 'm03-reading-the-fit', 14, 'What does an r-squared of 1.000000000 prove about a reading?', '["That the window was long enough, since a fit that clean cannot be produced on a stretch shorter than the floor of 0.4 log cycles the module sets.", "That the points that survived lie on a line, and nothing about the window they were taken from.", "That the estimator recovered a true exponent, which on the published power law is 1.350000000000 and on the channelling history is 1.600000000.", "That no point was dropped before the fit."]'::jsonb, 1, 'The published power law returns it on generated points and the two published power-law histories return it on opposite verdicts. It supports the line, and the label came from comparing one number against 1.3.'),
  ('intervention', 'beginner', 'module', 'm03-reading-the-fit', 15, 'What does the golden publish beside each of the four labelled histories?', '["A mechanism and a confidence for each, which is what makes the classifier the best checked part of this module against an independent route.", "A late derivative slope and the window it was taken over, in samples and in log cycles, so that the reading can be reproduced.", "A late derivative slope, and no expected mechanism, confidence, verdict or refusal at all.", "An expected verdict for each of the seven treatments, gated on the mechanism it publishes for that series."]'::jsonb, 2, 'The flat history publishes null for its slope. Every mechanism, confidence and verdict in this module is the classifier speaking with nothing asserted against it.'),
  ('intervention', 'beginner', 'module', 'm04-the-geometry-group', 1, 'What does pssDenominator return, and what is the 3/4 in it?', '["The natural log of the drainage radius over the wellbore radius, less 3/4, plus the skin, the 3/4 being the pseudo-steady-state constant for a circular drainage area.", "The same three terms with the 3/4 fitted to the shape of the drainage area, which is why a well off the centre of its area needs it re-tuned.", "The same three terms with the 3/4 standing in for the turbulent pressure drop near the wellbore.", "A productivity index, the 3/4 carrying the units."]'::jsonb, 0, 'Three terms and no more. On the published geometry the group is 7.900724584041 at zero skin, and the 3/4 is a convention rather than a fudge factor and is not adjustable.'),
  ('intervention', 'beginner', 'module', 'm04-the-geometry-group', 2, 'On the published geometry the drainage radius over the wellbore radius is 5714.285714286. What does the group come to at a skin of zero?', '["The ratio of 5714.285714286 with 3/4 taken off before the logarithm, the constant correcting the geometry rather than its log.", "8.650724584041, the logarithm of the ratio, which is the group whenever the skin entered is zero and nothing is left to subtract.", "7.900724584041, the log of that ratio less 3/4.", "0.496878274, the flow efficiency at that ratio."]'::jsonb, 2, 'The logarithm of 5714.285714286 is 8.650724584041, and taking 3/4 away leaves 7.900724584041. The published geometry is re = 2000.000000 ft and rw = 0.350000 ft.'),
  ('intervention', 'beginner', 'module', 'm04-the-geometry-group', 3, 'Which of these enters the pseudo-steady-state group?', '["The permeability, which is what makes the group a flow calculation rather than a piece of geometry and is why it is quoted in millidarcy.", "The skin, undivided.", "The drawdown, since the group is the denominator of a productivity index and a productivity index is a rate divided by a pressure difference.", "The net thickness, which enters through the same logarithm the two radii enter through and is why a thin interval returns a larger group."]'::jsonb, 1, 'The group is dimensionless: no permeability, no thickness, no viscosity, no pressure and no rate. Two radii through a logarithm, a constant of 3/4, and a skin added as itself.'),
  ('intervention', 'beginner', 'module', 'm04-the-geometry-group', 4, 'The published pair that takes a skin of 0.000 to 0.000 returns a multiplier of 1.000000000000000, with a departure from one of 0.0000e+0. Why is it exact?', '["Because the oracle asserts that identity separately, building both rates in SI and dividing them, which pins the case to the last bit at that one point.", "Because the multiplier is rounded to one whenever the two skins entered are equal, a guard that exists so a job that moved nothing cannot report a gain.", "Because the flow efficiency before and after are both 1.000000000, and a ratio of two efficiencies is exact when each of them is exact.", "It is one number divided by itself."]'::jsonb, 3, 'The multiplier divides the before group by the after group, and at an unchanged skin both are 7.900724584041 on the published geometry. It refuses to credit a job that moved nothing.'),
  ('intervention', 'beginner', 'module', 'm04-the-geometry-group', 5, 'Of the five published skin pairs, the one from 12.000 to -3.000 returns the largest multiplier at 4.060771880315. What makes it the largest?', '["It moves the group furthest, from a denominator of 19.900724584 down to 4.900724584, and the multiplier is the ratio of those two.", "It is the only pair that ends below zero skin, and a stimulated well is priced on a different branch of the calculation from a merely undamaged one.", "It removes fifteen units of skin, and the multiplier counts units removed, which is why it is roughly twice the 2.012565355861 that eight units returned.", "It starts from the largest flow efficiency of the five."]'::jsonb, 0, 'The pair from 8.000 to 0.000 moves 15.900724584 to 7.900724584 and returns 2.012565355861. What is priced is the ratio of the two groups, not the number of units.'),
  ('intervention', 'beginner', 'module', 'm04-the-geometry-group', 6, 'A twentyfold change in drainage radius, from 500 ft to 10000 ft on the published wellbore radius, moves the zero-skin denominator by how much, and what covers it?', '["By 2.995732274, which no plausible error in the skin could reach, so the radius is the number to spend an afternoon narrowing before anything else.", "By a factor of twenty, the group following the radius.", "By 2.995732274, which one unit of skin more than covers.", "By 8.650724584041, the whole published logarithm."]'::jsonb, 2, 'The denominator runs from 6.514430223 at 500 ft to 9.510162496 at 10000 ft. A radius enters through a logarithm, which forgives a guess, and the skin is added as itself, which does not.'),
  ('intervention', 'beginner', 'module', 'm04-the-geometry-group', 7, 'A design takes the after-skin to -8.0. What does the drainage radius do to that request?', '["Nothing, since the floor is a property of the wellbore radius alone and the drainage radius cancels out of it.", "It decides it: at 500 ft the floor is -6.514430223 and the request is below it, while at 10000 ft the floor is -9.510162496 and the same request is accepted in silence.", "It scales the multiplier the request returns, without changing whether the request is allowed, because the guard is a fixed limit on how deep a real treatment can go.", "It refuses the request either way, -8.0 being below everything the module calls achievable on any geometry at all."]'::jsonb, 1, 'The floor is the group set to zero, so it moves with the radii. An after-skin one geometry refuses outright is a legal answer on another, and nothing else about the design changed.'),
  ('intervention', 'beginner', 'module', 'm04-the-geometry-group', 8, 'At a skin of 8.0 the published geometry returns a flow efficiency of 0.496878274. Half of what?', '["Half of what this same well would make at zero skin on this same drainage radius, and nothing more absolute than that.", "Half of the rate the well made when it was drilled, the efficiency being referenced to the first flow after completion.", "Half of the field average for wells on the same drainage spacing.", "Half of the rate a fracture on this well would deliver."]'::jsonb, 0, 'The denominator at a skin of 8.0 is 15.900724584 against 7.900724584 at zero skin. It is a ratio of one well against a hypothetical version of itself, and it is not a rate.'),
  ('intervention', 'beginner', 'module', 'm04-the-geometry-group', 9, 'One unit of skin removed from 20.0 returns a multiplier of 1.037173720 and one unit removed from 1.0 returns 1.126570669. Which well gains more per unit?', '["The heavily damaged one, since 20.0 down to 19.0 removes the same unit from a larger denominator and a larger denominator is what a multiplier is built out of.", "Neither, each group having moved by exactly one.", "The heavily damaged one, at an efficiency of 0.283172738.", "The cleaner one, at 12.657067 percent against 3.717372 percent."]'::jsonb, 3, 'Every unit of skin moves the denominator by exactly one, so the unit is a smaller share of a bigger denominator. Removing all of the damage is a different question, and 12.000 to -3.000 returns 4.060771880315.'),
  ('intervention', 'beginner', 'module', 'm04-the-geometry-group', 10, 'What is minimumSkin on the published geometry, and what is it the skin of?', '["-7.900724584041, the deepest skin a matrix acid job on that geometry is expected to reach, which is why the number is computed on every call.", "-7.900724584041, the skin below which the fit quality of the pressure transient that measured it can no longer be trusted at all.", "-7.900724584041, the skin at which the group reaches zero and the productivity index goes infinite.", "7.900724584041, the group at zero skin, floor and group being one number."]'::jsonb, 2, 'It is the negative of the zero-skin denominator, published as -7.900724584041 and returned by the engine at a difference of 0.0000e+0. It is a property of the radii and knows nothing about acid or proppant.'),
  ('intervention', 'beginner', 'module', 'm04-the-geometry-group', 11, 'On the teaching geometry an after-skin of -5.000 returns 6.292734624 and one of -6.800 returns 26.457156986. What warning does the engine attach to the second?', '["A note naming the achievable range, because the refusal text puts a fracture at about -5 to -6 and the second request is past the deep end of that.", "None at all, no warning, no note and no flag, the two coming back with the same confidence.", "An ambiguous flag, which is the module''s general signal that a returned number sits close to a limit it was not built to describe.", "A reduced confidence field on the result."]'::jsonb, 1, 'The refusal fires only where the denominator reaches zero. Between the achievable range the text advertises and that pole, every request is accepted in silence, and the two answers differ by a factor of 4.204397383.'),
  ('intervention', 'beginner', 'module', 'm04-the-geometry-group', 12, 'The last after-skin the teaching geometry accepts is -7.361, which returns a multiplier of 20412.125808300 on a denominator of 0.000728083. What is that number describing?', '["A denominator going to zero, which is arithmetic rather than a stimulation, so a design sitting that close to the floor is one the equation cannot describe.", "A job that has removed all of the damage and some of the completion restriction with it, which is the largest prize this geometry has to offer.", "A numerical instability that the guard at the pole exists to catch, which is why the value is returned with ok = false beside it.", "The multiplier at the floor of -7.361728083308, which is where the module says a fracture stops."]'::jsonb, 0, 'The floor on that teaching geometry is -7.361728083308, and a request of -7.400 is refused with a sentence that then advises that real treatments reach about -3 to -5 on acid and -5 to -6 on a fracture.'),
  ('intervention', 'beginner', 'module', 'm04-the-geometry-group', 13, 'A vendor claims an uplift of 15.000 times. The inverse says the post-job skin that implies is -7.374009612 on the published geometry. What does the module say about it?', '["It refuses, the implied skin being 0.526714972 above a floor of -7.900724584 and therefore inside the band the guard exists to protect.", "It returns the claim with the floor attached, which is what makes the inverse the natural way to audit a number a contractor has quoted.", "Nothing, since the value comes back as a bare number with no flag, no warning and no note.", "It clamps the answer to the deepest skin the text calls achievable."]'::jsonb, 2, 'There is no plausibility check on that function of any kind. The floor it could compare against is one call away, and only a reader who calls minimumSkin and compares will notice.'),
  ('intervention', 'beginner', 'module', 'm04-the-geometry-group', 14, 'An open-hole radius is wanted and a nominal casing size is entered instead. What does the geometry group do?', '["It refuses, because a wellbore radius that does not match the completion is caught by the same check that catches a wellbore radius larger than the drainage radius.", "It returns a bare NaN, which is how every geometry this module cannot use is reported, and a caller running Number.isFinite will see it immediately.", "It absorbs the difference into the skin, the two being interchangeable through the equivalent wellbore radius, so the group is unchanged.", "It returns a legal group, a legal floor and a legal multiplier, all describing a well that does not exist."]'::jsonb, 3, 'Nothing about a geometry is checked except that the drainage radius is the larger and the wellbore radius is not zero. A wrong but legal radius is answered, not refused.'),
  ('intervention', 'beginner', 'module', 'm04-the-geometry-group', 15, 'How does skinFromPiRatio report a claimed uplift of zero, or a negative one?', '["As an object with ok = false and a sentence, the same contract skinPiMultiplier uses, which is what makes the two safe to call from one wrapper.", "As a bare NaN, which reads at the call site exactly as an answer does.", "As a skin at the geometry''s floor.", "As zero, a claim of no uplift implying no change of skin."]'::jsonb, 1, 'It returns a bare NaN for bad radii, for a negative claimed ratio and for a claimed ratio of zero, and all three read identically unless the caller runs Number.isFinite on the result.'),
  ('intervention', 'beginner', 'module', 'm05-four-pictures', 1, 'Why do channelling and coning call for opposite treatments?', '["Channelling arrives early and coning late, so the same squeeze is right on both wells and only the timing of it differs.", "Channelling is water down a path of its own, which is plumbing and can be sealed, while coning is water pulled through the same rock as the oil, and a cone re-forms above whatever is shut off.", "Channelling is a completion problem and coning a facilities one, so one is fixed at the well and the other downstream of it.", "Coning responds to a squeeze and channelling does not, the cone being a discrete path that can be isolated at the perforations that feed it."]'::jsonb, 1, 'That is why the mechanism table gives channelling treatable = true and coning treatable = false, and why a planner who squeezes without the diagnosis is wrong about half the time.'),
  ('intervention', 'beginner', 'module', 'm05-four-pictures', 2, 'The published coning derivative runs from 0.181405896 to 0.234375000 across 40 samples while the published channelling derivative runs from 1.273942946 to 11709.651930883. What is the coning derivative saying?', '["That the coning well is the drier of the two and therefore the safer candidate for a squeeze, the water having barely arrived at all across the record.", "That the coning series carries a measurement error, since a derivative that flat over 2.477121255 log cycles cannot be produced by a real completion.", "That the coning history has not yet reached its late window, which is why the derivative has not begun to climb the way the channelling one does.", "That the cone reached the perforations and stopped growing."]'::jsonb, 3, 'A cone stops growing once it is drawn to the perforations, so the derivative barely moves, and over the late window the published slope is -0.555098339661 rather than a climb.'),
  ('intervention', 'beginner', 'module', 'm05-four-pictures', 3, 'coningSlope is -0.1. What is it that separates the coning picture from the others?', '["The sign of the derivative, a falling derivative being qualitatively different from a rising one, which is why the engine calls that end of the reading the firm end.", "The size of the derivative, -0.1 being a tenth of the 1.3 that channelling has to clear.", "The fit quality, which on the published coning history is 0.948751314445 and is the lowest of the four, so a low fit quality is itself the coning signature.", "The level of the ratio, coning being the picture that never gets far above the plateau of 4.000000000 the history was built on."]'::jsonb, 0, 'The published coning history returns mechanism coning, treatable = false, confidence high and ambiguous false, and its note reads that the derivative is falling at a slope of -0.54.'),
  ('intervention', 'beginner', 'module', 'm05-four-pictures', 4, 'On the published coning history the engine returns -0.539955222223 and the independent route -0.555098339661. What does the confidence field returned beside the label know about that?', '["It carries the disagreement, which is why the confidence comes back low.", "It carries the disagreement through the fit quality of 0.948751314445, which is what falls when two estimators of a slope pull apart on the same points.", "Nothing at all, since the confidence is read off the engine''s own slope and never sees a second estimate.", "It sees the gap but treats a difference of 1.514312e-2 as within tolerance, having been calibrated on the published power law where the two agree to 0.0000e+0."]'::jsonb, 2, 'That history comes back at high confidence with ambiguous false. Both routes answer their own question honestly, and nothing in the return object compares them.'),
  ('intervention', 'beginner', 'module', 'm05-four-pictures', 5, 'The published displacement history runs its ratio from 0.500000000 to 150.000000000 and its derivative from 0.500000000 to 150.000000000. Why the same pair of numbers?', '["Because its derivative column was copied from its ratio column when the case was generated, which is why the published slope for it is exactly 1.000000000000.", "It is a t, and differentiating a power law gives a power law with the same exponent, so the ratio and its derivative share a log-log slope.", "Because the derivative is computed against ln t rather than t, and on a straight line those two are the same quantity.", "Because a swept reservoir delivers water at a constant rate, so the ratio and its rate of change are equal on any displacement well."]'::jsonb, 1, 'Its published lateDerivativeSlope is 1.000000000000 and over the window starting at t = 186.345364 days the engine returns 1.000000000000 with a fit quality of 1.000000000.'),
  ('intervention', 'beginner', 'module', 'm05-four-pictures', 6, 'The ambiguous band runs from 1.050000 to 1.550000. What does that do to the published displacement history, whose derivative slope is exactly 1.000000000?', '["It leaves the flag down, so a slope that the oracle''s own docstring calls the case needing the plot and a person is returned at high confidence with ambiguous false.", "It raises the flag, 1.000000000 being within 0.25 of the band''s lower edge and therefore inside the doubt the band exists to record.", "It has no effect either way, the band being applied to the ratio slope rather than to the derivative slope.", "It blocks the reading, a slope below the band being too shallow to carry a mechanism at all."]'::jsonb, 0, 'The band is 1.3 plus and minus 0.25, so 1.000000000 falls just outside it by a margin no field instrument could resolve, and the flag is a threshold test rather than a judgment.'),
  ('intervention', 'beginner', 'module', 'm05-four-pictures', 7, 'The not determined label carries treatable = false. What does its note say the label is for?', '["Rerunning the reading at a different window fraction until one of the three firm pictures comes back in its place, the label marking an incomplete run.", "Recording that the history is too short, six producing samples being the bare minimum a Chan reading will accept before it computes anything.", "Marking a well for a production log, which is the one instrument that settles the question the history could not settle on its own.", "Not spending money on a treatment chosen by guesswork."]'::jsonb, 3, 'The note reads that the history does not settle the question and that this is an answer. It is the one label whose note names a decision rather than a picture.'),
  ('intervention', 'beginner', 'module', 'm05-four-pictures', 8, 'A demonstration ratio rises exactly logarithmically, 20 samples from t = 20 to 2000 days with a derivative of exactly 0.900000000 at every one. What does the classifier return?', '["Mechanism displacement, a derivative that never changes being the flat picture and the reading the flat branch exists to give.", "Mechanism coning, since a derivative that is not climbing is read as the falling case whenever the ratio underneath it is still rising.", "Mechanism indeterminate at low confidence, with the derivative fit quality at 0.000000000 against a floor of 0.5.", "A refusal with ok = false, a constant column having no line to fit."]'::jsonb, 2, 'It prints that the derivative scatters too much to carry a slope and that the fit explains only 0.0 percent of it, on a series with no scatter in it anywhere. The ratio underneath climbs from 4.696159046 to 8.840812214.'),
  ('intervention', 'beginner', 'module', 'm05-four-pictures', 9, 'The published flat history sits at a ratio of 1.200000000 with every derivative at 0.000000000. Which of the four labels does it come back under?', '["Displacement, with a ratio slope of 0.000000000, a ratio fit quality of 0.000000000 and the confidence field not populated at all.", "Not determined, since a constant column carries no slope and the label for a history that settles nothing is the indeterminate one.", "Coning, a derivative of 0.000000000 being below the coning threshold of -0.1 and therefore on the falling side of it.", "It returns ok = false, no mechanism being assignable to a series that never moves."]'::jsonb, 0, 'The note reads that nothing is changing and that there is no mechanism to diagnose and nothing for an intervention to fix, which it calls a finding rather than a failure to reach one.'),
  ('intervention', 'beginner', 'module', 'm05-four-pictures', 10, 'minSpanDecades is 0.4 and minWor is 0.1. What does each of the two gate?', '["The span in log cycles and the fit quality, the two being the pair of floors that decide whether a slope may be read at all on a window.", "The span of the fit in log cycles, and the level of the ratio on the last sample.", "The producing days the window covers and the number of samples inside it, which is why a short record fails both at once.", "The ratio slope and the derivative slope, each with its own floor."]'::jsonb, 1, 'They are shipped defaults sitting beside a channellingSlope of 1.3, a coningSlope of -0.1, an ambiguousBand of 0.25 and a minR2 of 0.5, all round on purpose because they are boundaries drawn between pictures.'),
  ('intervention', 'beginner', 'module', 'm05-four-pictures', 11, 'Reading the teaching well through a moving window, the derivative slope goes 1.336892539, then 1.292632524. What happens to the water shutoff between those two rows?', '["It stays a candidate on both, the two slopes being within 0.25 of each other and therefore inside one band with one verdict attached to it.", "It turns from blocked into candidate, the shallower slope being the one that says the water has a path of its own to seal.", "It turns from candidate into blocked.", "It becomes marginal, which is the verdict the screening gives whenever a reading sits within the ambiguous band around the threshold."]'::jsonb, 2, 'The margins against 1.3 are 0.036892539 and -0.007367476. The whole spend turns on a crossing of 1.3 that no field instrument could resolve, on 38 samples with not one datum changed.'),
  ('intervention', 'beginner', 'module', 'm05-four-pictures', 12, 'Coning carries treatable = false. Which treatment does a coning reading nonetheless promote to a candidate?', '["None, treatable = false meaning that nothing on the well is worth doing and every treatment in the table is blocked behind that flag.", "The water shutoff squeeze, which is blocked on displacement and allowed on coning because a cone is a water path like any other.", "Recompletion, which on a coning reading comes back a candidate because moving the perforations up is what puts distance between them and the cone.", "Reducing the drawdown."]'::jsonb, 3, 'The published coning history gives waterShutoff blocked, rateReduction candidate and recompletion consider. Treatable = false means nothing to seal rather than nothing to do.'),
  ('intervention', 'beginner', 'module', 'm05-four-pictures', 13, 'The screening is handed no diagnosis at all. What does the water shutoff come back as?', '["Blocked, with a reason saying that the mechanism has not been established and that more production history or a production log is wanted before anything is spent.", "A candidate, since with no mechanism to rule it out the screening falls back to the water cut, which is what a shutoff is aimed at in the first place.", "Unknown, which is the verdict reserved for a treatment whose gate cannot be evaluated from what was supplied.", "Marginal, the absence of a diagnosis being treated as doubt rather than as a block."]'::jsonb, 0, 'It says a shutoff squeeze on a coning well is money down a hole and that this history does not say which it is. That refusal is the part of the module that gets this right.'),
  ('intervention', 'beginner', 'module', 'm05-four-pictures', 14, 'Matrix acid is gated on the skin alone. What does it return when no skin was entered?', '["No, an absent skin being treated as an undamaged well and therefore as nothing for an acid job to remove from the near wellbore.", "Unknown, which is a different verdict from the no it returns at or below a skin of 0.", "Candidate, because the gate is above a skin of 2 and an unentered field is read as zero, which then falls through to the damaged branch.", "Marginal, the verdict it gives above a skin of 0."]'::jsonb, 1, 'It is a candidate above a skin of 2 and marginal above 0. The mechanism gates the water treatments only, so a well can be untreatable for water and still worth a job.'),
  ('intervention', 'beginner', 'module', 'm05-four-pictures', 15, 'What does the word channelling on its own establish in a report?', '["That the derivative climbed faster than proportionally, which is the reading and is what a mechanism label is a compact way of stating.", "That the fit cleared the floors of 0.5 on quality and 0.4 in log cycles, which is what the label certifies before it is issued at all.", "Very little, since it is one fitted slope compared against one constant somebody chose.", "That the water has a path of its own."]'::jsonb, 2, 'A defensible line names the slope, the window in samples and log cycles, the threshold it was compared against and the margin. Change the window, the constant or the floor and the label can change with no datum touched.'),
  ('intervention', 'beginner', 'module', 'm06-the-associate-reading', 1, 'An Associate reading of a ratio history begins with which call?', '["The diagnosis at its default window, its ratio slope taken as the reading.", "minimumSkin on the geometry, so that the floor is known before any series is looked at and the fit can be checked against it.", "logLogSlope on the whole raw history, with no late window and no fraction anywhere near it.", "The diagnosis at each of several window fractions, the reading being the slope that the largest number of those windows agree on."]'::jsonb, 2, 'Hand in every sample you were given, in producing days against the ratio. A slope read back out of a diagnosis was fitted on a window and this one is not.'),
  ('intervention', 'beginner', 'module', 'm06-the-associate-reading', 2, 'Why must the slope from a diagnosis not be copied into an Associate reading of the same history?', '["Because it was measured over a late window and on the samples that survived a filter, while the Associate reading is the whole raw history with nothing removed.", "Because the diagnosis reports its slope rounded, and full precision is wanted.", "Because the diagnosis returns the derivative slope only, and no ratio slope is available anywhere in that object to be copied out of it.", "Because a diagnosis refuses on any history that a whole-history fit would accept, so the two calls never succeed on the same series."]'::jsonb, 0, 'On the teaching well the whole history returns a ratio slope of 1.098217467822 and the default window returns 1.040602176. Both are true of what they read, and only one of them is the Associate reading.'),
  ('intervention', 'beginner', 'module', 'm06-the-associate-reading', 3, 'Which four members of a fit return belong together and should be written in one pass?', '["The slope, the fit quality, the count and the confidence, the confidence being what the other three are worth taken together as a reading.", "The slope, the intercept, the fit quality and the span.", "The slope, the intercept, the count and the mechanism the slope implies once it has been compared against the thresholds.", "The slope and the fit quality only, the count and the span describing the input rather than the line drawn through it."]'::jsonb, 1, 'They come out of one call, and the published power law returns 1.350000000000, 1.308332819650, 1.000000000000 and 2.000000000 over its eleven points. Rounding on the way is how a reading stops being checkable.'),
  ('intervention', 'beginner', 'module', 'm06-the-associate-reading', 4, 'What is the one warning a reader gets that a fit dropped points?', '["A flag on the return, raised whenever the filter removes a point, which is why the count and the array length can be trusted to agree.", "The fit quality, which falls as points are removed.", "The refusal sentence, which names the points removed.", "The returned count set against the length of the array that was handed in."]'::jsonb, 3, 'Nothing announces the removal. The teaching well''s derivative fit returns n = 34 on 38 samples handed in, and the reported span of 2.122891107 is short of the 2.380211242 the ratio fit reports on the same series.'),
  ('intervention', 'beginner', 'module', 'm06-the-associate-reading', 5, 'In what order is the pseudo-steady-state group built?', '["Add the skin to the drainage radius, take the log of that over the wellbore radius, then subtract 3/4 from what comes out of it.", "Take the log of each radius, subtract one from the other, then apply 3/4.", "Take the log of the drainage radius over the wellbore radius, subtract 3/4, then add the skin.", "Subtract 3/4 from the ratio of the radii, take the log, and add the skin, which is the order that makes the floor come out negative."]'::jsonb, 2, 'On the published geometry that is a log of 8.650724584041, less 3/4, giving 7.900724584041 at zero skin. The floor is then the same group with the skin removed and the sign flipped, -7.900724584041.'),
  ('intervention', 'beginner', 'module', 'm06-the-associate-reading', 6, 'How should the floor a geometry allows be read at a call site?', '["Through the ok field on the result, which is set false whenever the radii cannot be used and carries a sentence naming what was wrong with them.", "Through Number.isFinite, because a bad geometry comes back as a bare NaN with no message and no flag.", "By comparing it against zero, a floor at or above zero being the signal that the geometry was rejected.", "By catching the exception it throws on a wellbore radius larger than the drainage radius."]'::jsonb, 1, 'skinPiMultiplier reports failure as ok = false with a sentence, while the group, the floor and the inverse return a bare NaN. A call site testing only for an ok flag carries that NaN forward and prints it as an answer.'),
  ('intervention', 'beginner', 'module', 'm06-the-associate-reading', 7, 'A single point is dropped from a fit. Which members of the return move because of it?', '["The count and the span, since the span is measured across the points that survived rather than across the ones handed in.", "The count alone, the span being computed from the window before the filter runs.", "The count and the intercept, the line being re-pinned at x = 1.000000 once a point has gone.", "The count and the fit quality, which always rises when a point is removed because there is less left for the line to miss."]'::jsonb, 0, 'The six-point demonstration returns n = 4 and a span of 0.903089987 while the points handed in cover 1.505149978 log cycles, a shortfall of 0.602059991.'),
  ('intervention', 'beginner', 'module', 'm06-the-associate-reading', 8, 'Which parts of this module have an independent check behind them?', '["The classifier as well, since the golden publishes a labelled history for each of the four mechanisms and the label is what those histories are named for.", "The screening, which is checked against the published verdicts for each of the seven treatments on the same well row.", "All of the exported functions, the oracle being independent by construction and therefore covering everything the module returns.", "The log-log slope and the skin uplift, and nothing else."]'::jsonb, 3, 'The oracle checks the slope by Theil-Sen and the uplift by a full radial Darcy rate in SI. chanDiagnosis, screenTreatments, rankTreatments and skinFromPiRatio are asserted against nothing at all.'),
  ('intervention', 'beginner', 'module', 'm06-the-associate-reading', 9, 'What is the only number carrying a physical unit that this module produces for itself?', '["The span, which is counted in log cycles of producing time and therefore carries the day of the axis it was measured along into the return.", "The day the late window starts on.", "The multiplier, which is a fold increase on a rate and so carries stock tank barrels a day once the geometry has been supplied.", "The flow efficiency, being a rate against the rate of an undamaged well on the same drainage radius."]'::jsonb, 1, 'Slopes, intercepts, fit qualities, spans, the group and the skin are all dimensionless. The module sizes no treatment and returns no barrel, no pressure and no time anywhere else.'),
  ('intervention', 'beginner', 'module', 'm06-the-associate-reading', 10, 'A contractor asks what a multiplier of 2.012565355861 means in barrels.', '["It is the rate the well will make after the job, in stock tank barrels a day, once the drainage radius is supplied to convert it.", "It is the gain in barrels a day per unit of skin removed, so eight units returns eight times it on the published geometry.", "It does not mean anything in barrels, being a fold increase rather than a rate.", "It becomes barrels once the efficiency of 0.496878274 is applied."]'::jsonb, 2, 'No permeability, no thickness, no viscosity, no pressure and no rate enters the group, so nothing in the return can be turned into a rate without a productivity calculation this module does not do.'),
  ('intervention', 'beginner', 'module', 'm06-the-associate-reading', 11, 'Which input error moves the answer most, and why?', '["A skin entered with the wrong sign, because the group adds the skin undivided while the radii enter through a logarithm that forgives a bad guess.", "An error in the drainage radius, since a twentyfold change in it moves the zero-skin denominator by 2.995732274 and no skin error is that large.", "An error in the wellbore radius, which sits underneath the logarithm and is therefore the more sensitive of the two radii by a wide margin.", "A fit quality quoted as a percentage where the return wants a fraction."]'::jsonb, 0, 'That twentyfold radius sweep moves the denominator by 2.995732274, which one unit of skin more than covers. Keep radii in ft and the skin dimensionless.'),
  ('intervention', 'beginner', 'module', 'm06-the-associate-reading', 12, 'What is true of the six constants that turn a slope into a label?', '["They are calibrated on the four published histories, which is what the golden publishes those four histories for and why each is labelled.", "They are fixed in the engine and cannot be changed at a call site.", "They are conventions of the same kind as the 3/4.", "They are shipped defaults, all overridable, and none of them was measured."]'::jsonb, 3, 'A derivative slope meets a channellingSlope of 1.3, a coningSlope of -0.1 and an ambiguousBand of 0.25, with minR2 at 0.5, minSpanDecades at 0.4 and minWor at 0.1 deciding whether the reading is allowed at all.'),
  ('intervention', 'beginner', 'module', 'm06-the-associate-reading', 13, 'Which step, done out of order, leaves every later number defensible on its own and the reading wrong?', '["Computing the floor before the group, which flips the sign of both and is caught by any check on the geometry.", "Taking the exponential of the intercept before the slope is recorded, which loses the coefficient.", "Choosing a window before the raw history has been fitted, since everything after that is honest arithmetic on the wrong set of points.", "Quoting the fit quality as a fraction where the module''s own sentences quote a percentage, which moves the number by two orders of magnitude."]'::jsonb, 2, 'Each later number is then true of the window that was chosen. The window is not in the return object, so nothing downstream can tell that the wrong points were read.'),
  ('intervention', 'beginner', 'module', 'm06-the-associate-reading', 14, 'What is the 3/4 in the group?', '["A tuned constant, fitted so that the group reproduces the published multipliers on the five skin pairs the case file carries.", "The pseudo-steady-state constant for a circular drainage area.", "A safety factor, applied so that a floor sits above the skin at which the productivity index would actually go infinite on the geometry.", "A conversion, carrying the foot of the two radii out of the group so that what is left of it is dimensionless."]'::jsonb, 1, 'It is that convention rather than a fudge and it is not adjustable. On the published geometry it takes 8.650724584041 down to 7.900724584041.'),
  ('intervention', 'beginner', 'module', 'm06-the-associate-reading', 15, 'What does a fit return establish, and what does it leave open?', '["It establishes a slope, an intercept, a fit quality, a count and a span, and leaves open the window, the column and the points the filter removed.", "It establishes the mechanism and the confidence, and leaves open only the treatment that should follow from them.", "It establishes the window it was taken over, and leaves open how many points were inside it.", "It establishes that the data is a power law, and leaves open which exponent describes it best."]'::jsonb, 0, 'Nothing in that call knows the x axis was days or the y column a ratio, and it will fit a straight line through anything positive.'),
  ('intervention', 'beginner', 'final', null, 1, 'One reading is repeated after the producing time column is recounted on a different base, and a second after the drainage radius is revised from 500 ft to 10000 ft. What moved?', '["The intercept moved on the first and the geometry group moved by 2.995732274 on the second, while the fitted slope did not move at all.", "Both readings moved by the same proportion, since a change of base and a change of radius both enter through a logarithm.", "Neither moved, both quantities being dimensionless and therefore immune to what their inputs are counted in.", "The slope moved on the first and the floor stayed put on the second, a floor being a property of the skin rather than of the radii."]'::jsonb, 0, 'A log-log slope is d ln y / d ln x and carries no unit. The intercept is the log of a value at one on the x axis, and the group runs from 6.514430223 to 9.510162496 across that sweep.'),
  ('intervention', 'beginner', 'final', null, 2, 'Two floors sit in this module: a span floor of 0.4 log cycles and the skin at which the geometry group reaches zero. Which of the two stops an answer being returned?', '["Both, the geometry floor refusing any design that reaches it and the span floor refusing any window shorter than it, which is what makes them a matched pair.", "The skin floor, which is why a request past it comes back with a sentence naming the achievable range for acid and for a fracture.", "The span floor, while the skin floor is computed on every call and compared against nothing but zero.", "Neither, both being advisory values reported beside the answer rather than gates on it."]'::jsonb, 2, 'The skin floor is -7.900724584041 on the published geometry and is returned inside a successful result. Between the achievable range and the pole every request is accepted in silence.'),
  ('intervention', 'beginner', 'final', null, 3, 'The published channelling history was built with an exponent of 1.600000000 and publishes a late derivative slope of 1.600000000000. What does that equality cost the classifier?', '["Nothing, the equality being a property of that one generated series rather than of power laws in general.", "Every separator except steepness, since the ratio and its derivative carry one slope and only the size of it is left to tell displacement from channelling.", "Its fit quality gate, because two identical slopes always return 1.000000000 and the floor of 0.5 can then never fire on any history.", "Its coning branch, which cannot fire on a series whose ratio and derivative agree."]'::jsonb, 1, 'The published displacement history does the same at 1.000000000 twice. The classifier is left with one comparison against a threshold of 1.3 that somebody typed.'),
  ('intervention', 'beginner', 'final', null, 4, 'On the published coning history the two independent slope routes give -0.539955222223 and -0.555098339661. Which returned field records that disagreement?', '["The fit quality, which comes back at 0.948751314445 and is the field that falls when two estimators of one slope pull apart on the same points.", "The confidence, which comes back low on that history for exactly this reason and is the field a reader is meant to check first.", "The ambiguous flag, which is raised whenever a reading could be defended two ways and is what a difference of 1.514312e-2 raises it for.", "None of them."]'::jsonb, 3, 'The engine never sees the second estimate. That history returns high confidence with ambiguous false, and the fit quality describes the engine''s own line only.'),
  ('intervention', 'beginner', 'final', null, 5, 'A wrapper is written that returns nothing whenever a result''s ok field is falsy. What does it do to a perfectly good pssDenominator call?', '["Passes it through, a bare number being truthy.", "Reports it correctly either way, the module using one failure contract throughout and the ok field being present on every return it makes.", "Reports it as a failure, because a bare number has no ok property and an absent property is falsy.", "Throws, because reading a property off a number is an error rather than a value that can be tested for truth."]'::jsonb, 2, 'skinPiMultiplier returns an object with ok = false. pssDenominator, minimumSkin and skinFromPiRatio return a bare NaN, so only Number.isFinite separates an answer from a refusal on those three.'),
  ('intervention', 'beginner', 'final', null, 6, 'The teaching well''s ratio fit returns n = 38 with a span of 2.380211242 and its derivative fit returns n = 34 with a span of 2.122891107. What is that pair of differences?', '["The only visible trace that four samples were removed, since nothing else in the return says a point was dropped.", "The difference between the whole history and the late window, which is what the two fits were taken over.", "A rounding difference, the two spans being measured on the same axis and differing only in how the endpoints were counted.", "The gap between the two estimators, one route reading 38 samples and the other only the 34 it could pair."]'::jsonb, 0, 'The four dropped samples carry a negative derivative and a log axis has nothing to say about them, so the count and the span move together and nothing else does.'),
  ('intervention', 'beginner', 'final', null, 7, 'A well reads ordinary displacement, so the water shutoff is blocked, and its skin is 8.0. Is there anything left to do on it?', '["No, a displacement reading meaning that no treatment on this well will change anything, which is what the mechanism note says in as many words.", "Yes, since matrix acid is gated on the skin alone and is a candidate above a skin of 2, the mechanism gating the water treatments only.", "No, because a blocked water shutoff blocks every treatment ranked below it in the same screening pass.", "Yes, but only reducing the drawdown, which is the treatment a blocked squeeze always falls back to."]'::jsonb, 1, 'At a skin of 8.0 the denominator is 15.900724584 against 7.900724584 undamaged, a flow efficiency of 0.496878274. A well can be untreatable for water and still worth a job.'),
  ('intervention', 'beginner', 'final', null, 8, 'An Associate reading records four fit members, a count and a geometry group. Which single comparison is the whole of its quality control?', '["The fit quality against the floor of 0.5, which is the check the module itself makes before it will read a mechanism off a slope at all.", "The slope against the threshold of 1.3, which is where the reading either becomes a mechanism or stops being one.", "The span against the floor of 0.4 log cycles, which is the only member of the return that describes the data rather than the line.", "The returned count against the number of samples handed in."]'::jsonb, 3, 'Nothing announces a drop. On the published power law the count comes back at 11 on 11 handed in, and on the teaching derivative at 34 on 38.'),
  ('intervention', 'beginner', 'final', null, 9, 'The independent oracle runs two checks. Which two functions do they land on, and what does each route share with the engine?', '["The classifier and the screening, checked against the four labelled histories and the seven treatments the case file publishes for them.", "The log-log slope and the classifier, the first by Theil-Sen and the second against the mechanism the golden names beside each history.", "The log-log slope and the skin uplift, and neither route shares any arithmetic with the engine at all.", "The log-log slope alone, run twice by least squares."]'::jsonb, 2, 'Theil-Sen is the median of every pairwise slope, with no mean, no square and no covariance in common with least squares, and the uplift check is a full radial Darcy rate in SI divided as two real flow rates.'),
  ('intervention', 'beginner', 'final', null, 10, 'The fit reproduces the published slope at a difference of 0.0000e+0 and the multiplier reproduces published case 1 at 0.0000e+0. What do those two zeros have in common?', '["Each is an agreement between two independent arithmetics, and neither is a statement about a well.", "Each is a check the golden asserts on every one of the module''s exported functions, which is what makes the module well covered as a whole.", "Each is a floating point coincidence at the precision the case file happens to publish, and a longer series would separate the routes.", "Each says the model behind the calculation is the right one for a producing well of that kind."]'::jsonb, 0, 'There is no well in the power-law case and no rate in the multiplier. A multiplier is a fold increase, and the exactness belongs to the transform and to the ratio of two groups.'),
  ('intervention', 'beginner', 'final', null, 11, 'The published flat history comes back labelled displacement. What did the fitted line contribute to that label?', '["A ratio slope of 0.000000000 at a fit quality of 0.000000000, which is what the label was read off.", "Nothing, because the derivative fit over that window returns ok = false on n = 0 and the label came off the derivative being zero throughout.", "A derivative slope of 0.000000000, which sits above the coning threshold of -0.1 and below the channelling threshold of 1.3.", "A span of 2.477121255 log cycles, which cleared the floor of 0.4 and so allowed a mechanism to be assigned."]'::jsonb, 1, 'Every derivative in that series is 0.000000000, so no point survives the positive filter. The ratio fit''s own numbers are in the same return and had no part in the label.'),
  ('intervention', 'beginner', 'final', null, 12, 'A vendor claims an uplift of 12.000 times on the published geometry, which the inverse says implies a post-job skin of -7.242330869. What does auditing that claim require?', '["Nothing further, the inverse refusing any claim that implies a skin past the floor and returning a value only where the claim is physically reachable.", "Re-running the multiplier forward from the implied skin, which is the round trip and the check the oracle makes on this function.", "Reading the sign, a negative implied skin being the test.", "Calling minimumSkin and comparing, since the inverse says nothing about whether an implied skin is reachable."]'::jsonb, 3, 'The floor on that geometry is -7.900724584, and there is no plausibility check on the inverse of any kind. Every implied skin is negative and every one of them looks like a stimulated well.'),
  ('intervention', 'beginner', 'final', null, 13, 'The window dial moves the teaching well''s derivative slope by 0.370920348 in total, while the verdict changes on a margin of 0.007367476 against the threshold. What follows from the comparison?', '["That the dial is safe, since a movement of 0.370920348 across the whole range is small beside a threshold of 1.3.", "That the margin is what should be widened, the ambiguous band of 0.25 being too narrow to catch a movement of that size.", "The analyst''s choice of window is worth far more than the margin that decides the spend.", "That the two are unrelated, one moving the slope and one the threshold."]'::jsonb, 2, 'One history, not one datum changed, and the derivative slope runs from 1.229355999 to 1.600276347. The dial has a default of 0.5 and no guidance beside it.'),
  ('intervention', 'beginner', 'final', null, 14, 'One count in this module is checked before any arithmetic runs and another is reported after a filter. Which is which?', '["The classifier checks the sample count first and refuses a five sample history outright, while the fit reports its count after every non-positive y has been dropped.", "The fit checks its count first, which is why it can refuse two points before transforming them.", "Both are checked before, the module counting its input at every entry point and refusing early wherever the count is short.", "Both are reported after, the classifier''s refusal on five samples being issued once the filter has run and found nothing left."]'::jsonb, 0, 'The refusal words are that a Chan reading needs a history and not a handful of points and that six producing samples is the bare minimum. The fit''s own refusal returns n = 2 on four points of which two survived.'),
  ('intervention', 'beginner', 'final', null, 15, 'Of the five exported calculations, how many take a series?', '["Two, logLogSlope and skinPiMultiplier, the second reading a rate history to establish what the well made before the job was designed.", "One, logLogSlope.", "Three, the two that price skin taking a series of pressures alongside the geometry they are handed.", "All five, a series being the input this module is built around."]'::jsonb, 1, 'The geometry group, the floor, the multiplier and the inverse take radii and skins and nothing else. That is why the fit and the geometry can be worked without a classifier anywhere near them.'),
  ('intervention', 'beginner', 'final', null, 16, 'What does this module size?', '["The squeeze, in barrels of gel, once the mechanism has been established and the water cut supplied alongside it.", "The acid job, through the multiplier, which converts to a volume when the drainage radius and the wellbore radius are both known.", "The rate uplift, which is what a multiplier of 2.012565355861 states on the published geometry.", "Nothing at all."]'::jsonb, 3, 'It is a diagnostic. It names a picture and prices removing skin as a pure ratio, and the only number with a unit it produces itself is the day the late window starts on.'),
  ('intervention', 'beginner', 'final', null, 17, 'The classifier refuses a five sample history and names six as the bare minimum. What else does that sentence say?', '["That six samples is enough for a reading of any window, which is why the floor was set there.", "That the six have to be evenly spaced in producing time before the count is accepted.", "That a useful reading wants far more than six.", "That a shorter history should be run at a wider window fraction instead, since a wider window recovers the samples the count is short of."]'::jsonb, 2, 'It is the one place a count is checked before any arithmetic runs, and it returns ok = false with mechanism indeterminate and every fit field absent.'),
  ('intervention', 'beginner', 'final', null, 18, 'What does the displacement note say about intervention?', '["That the water is simply arriving as it does in a swept reservoir, so this is not a well problem and no intervention on this well will change it.", "That the water is arriving through a path of its own, which is plumbing and can be sealed.", "That the history does not settle the question, so no treatment should be chosen by guesswork.", "That the cone re-forms above whatever is shut off."]'::jsonb, 0, 'Displacement carries treatable = false. It is one of the two labels whose note is a decision to spend nothing rather than a description of a defect.'),
  ('intervention', 'beginner', 'final', null, 19, 'The published pair at x = 10.000000 and y = 82.832682127 becomes what pair before the line is fitted?', '["x = 10.000000 and ln y = 4.416822695, only the y column being transformed because it is the one that spans orders of magnitude.", "ln x = 2.302585093 and ln y = 4.416822695.", "ln x = 2.302585093 and y = 82.832682127, the x axis being the one a log-log slope is measured along.", "The pair as it stands, the transform being applied to the fitted slope afterwards rather than to the data."]'::jsonb, 1, 'Both columns go through a natural log and one straight line is fitted to the pairs. On these eleven published points the fit is exact at an r-squared of 1.000000000000.'),
  ('intervention', 'beginner', 'final', null, 20, 'The published intercept of 1.308332819650 is also the ln y of the first published pair. Coincidence or construction?', '["Coincidence, the intercept being fitted through all eleven points while ln y at the first pair is one measurement among them.", "Construction, the fit pinning its line through the first pair of any series it is handed and reporting that pair''s ln y as the intercept.", "Construction, since that pair sits at x = 1.000000 where ln x is zero, which is where an intercept is read.", "Coincidence, and it would not survive the addition of a twelfth point at a longer x."]'::jsonb, 2, 'The intercept is the height of the line where ln x is zero. The published pair there is x = 1.000000 with y = 3.700000000, and the published true intercept is 1.308332819650.'),
  ('intervention', 'beginner', 'final', null, 21, 'The published power law returns a fit quality of 1.000000000000 while its y column climbs from 3.700000000 to 1854.392764421. What is straight?', '["The transformed data, since a power law is a straight line only once both axes are logarithmic.", "The raw data, a fit quality that high being unreachable on a curve.", "The residuals, which lie along a straight line of their own once the fit has been subtracted from the points.", "The x column, which runs from 1.000000 to 100.000000 in even steps of the log axis."]'::jsonb, 0, 'The eleven points span 2.000000000 log cycles and every pair lands on one line in logs. Straightness lives in the transform, not in the column.'),
  ('intervention', 'beginner', 'final', null, 22, 'A plateau shape is fitted by least squares at -0.539955222223 and by Theil-Sen at -0.555098339661. Which of the two has measured a slope?', '["The Theil-Sen route, being a median of pairwise slopes and therefore robust to the curvature that defeats least squares on that shape.", "Neither, a plateau form having no single log-log slope for either route to find.", "The least squares route, being the one the engine reports and the one every later threshold comparison is made against.", "Both, to within a difference of 1.514312e-2."]'::jsonb, 1, 'There is no noise in that series at all. Two estimators weight a curved log-log trend differently and each answers its own question honestly.'),
  ('intervention', 'beginner', 'final', null, 23, 'minR2 is 0.5. What does a derivative fit below it stop?', '["The fit, which comes back with ok = false and no slope at all once the quality falls under the floor.", "The span check, which is skipped whenever the quality gate has already fired on the same fit.", "The mechanism, which is refused as a reading of noise while the fit itself still returned a slope.", "The screening, which is what the floor was placed there to gate."]'::jsonb, 2, 'A demonstration whose derivative is exactly 0.900000000 at every sample returns a derivative fit quality of 0.000000000 and the sentence that the fit explains only 0.0 percent of it, on data with no scatter in it.'),
  ('intervention', 'beginner', 'final', null, 24, 'A window is reported as covering 2.000000000 log cycles. How many samples is that?', '["Eleven, which is what the published power law holds across that span and what a span of two cycles is defined as holding.", "At least three, the span being computed only once the minimum count for a fit has been met and reported alongside it.", "Forty, the sampling of the published histories being the standard this module reports spans against.", "The span does not say, the two members answering different questions."]'::jsonb, 3, 'The published power law reports 2.000000000 on eleven points while the published histories report 2.477121255 on forty. A long-looking record can still be a short reading and a short one a dense reading.'),
  ('intervention', 'beginner', 'final', null, 25, 'The teaching well''s four dropped samples carry derivatives of -9.958064965, -8.779998197, -7.741300002 and -6.825482691. What made them undrawable?', '["A log axis has nothing to say about a negative number, so the filter removes them before the line is fitted.", "Their size, the four being an order of magnitude below the samples the fit kept.", "Their spacing, the four sitting so far out in producing time that the geometric sampling leaves gaps a fit cannot bridge.", "Their fit quality, which falls below the floor of 0.5 when they are included."]'::jsonb, 0, 'The fit returns n = 34 on the 38 handed to it and says nothing about the removal. Those four sit from 2308.407093 to 3600.000000 days, after the well was beaned back on day 2200.'),
  ('intervention', 'beginner', 'final', null, 26, 'A demonstration is handed six points, two of them negative, and returns a fit quality of 1.000000000 on the four that survived. Is that a good fit or a good reading?', '["A good reading, an r-squared that high on a slope of 1.000000000 being about as clean a result as this module produces.", "A good fit and no reading at all, since the line is flawless through a subset chosen by a filter.", "Neither, the fit having returned ok = false once two of the six points were found to be unusable.", "A good reading of four points, which is the count the fit reports and therefore the count a reader is meant to quote."]'::jsonb, 1, 'The four cover 0.903089987 log cycles against the 1.505149978 the six were handed in over, a shortfall of 0.602059991, and nothing in the object mentions any of it.'),
  ('intervention', 'beginner', 'final', null, 27, 'At a skin of -3.0 the published geometry returns a flow efficiency of 1.612154376. What is an efficiency above one?', '["An arithmetic artefact of the group approaching zero, which is what every efficiency above one on this geometry is.", "A reading that the geometry has been entered wrongly, since no completion delivers more than an undamaged one.", "A well making more than the same well would make undamaged on the same drainage radius.", "A rate above the well''s tested rate, expressed as a multiple of it."]'::jsonb, 2, 'The denominator at a skin of -3.0 is 4.900724584 against 7.900724584 at zero skin. A negative skin is a stimulated well and the efficiency is a ratio against one hypothetical version of itself.'),
  ('intervention', 'beginner', 'final', null, 28, 'One design reports a denominator of 0.900724584 and a flow efficiency of 8.771520978. What is behind a number that large?', '["A fracture result, -7.0 being within the range the module''s own refusal text calls achievable on a fracture rather than on acid.", "The largest honest prize this geometry offers, since the floor at -7.900724584041 has not been reached and the answer is therefore inside the guard.", "A refusal, the guard firing once the denominator falls below one.", "A group on its way to zero, which is arithmetic rather than a stimulation."]'::jsonb, 3, 'The floor on that geometry is -7.900724584041 and the refusal fires only where the denominator reaches zero. A design that close to the floor is one the equation cannot describe.'),
  ('intervention', 'beginner', 'final', null, 29, 'The engine reproduces published case 5, a skin of 12.000 taken to -3.000, with a difference of -8.8818e-16 from the published multiplier of 4.060771880315. What does a difference that size mean?', '["That two independent routes onto one quantity agree to the precision the arithmetic can carry, which is what the check was written to establish.", "That the engine is slightly low, a bias that grows with the number of units of skin removed.", "That the published value was rounded before it was committed to the case file.", "That the two routes disagree, which is why the difference is reported at all."]'::jsonb, 0, 'The oracle builds a full radial Darcy rate in SI and divides two real flow rates; the engine divides 19.900724584 by 4.900724584. Same physics, no shared arithmetic.'),
  ('intervention', 'beginner', 'final', null, 30, 'A design takes the after-skin below everything the refusal text calls achievable, but not as far as the pole. What comes back?', '["A refusal naming the achievable range, which is the limit the guard was written to enforce and the one its sentence advertises.", "A larger multiplier, ok = true, and no warning, no note and no flag of any kind.", "The answer with the floor attached to it, so that a reader can see how far past the range the request sits.", "The answer with its confidence reduced."]'::jsonb, 1, 'On the teaching geometry an after-skin of -5.000 returns 6.292734624 and one of -6.800 returns 26.457156986, a factor of 4.204397383, and the deepest skin the text calls real for a fracture is -6.'),
  ('intervention', 'beginner', 'final', null, 31, 'The before-skin and the after-skin are both guarded against the floor. How do the two refusals differ?', '["The before-skin refusal returns a bare NaN while the after-skin refusal returns an object with ok = false and a sentence.", "The before-skin refusal fires at the achievable range and the after-skin refusal at the pole, which is why the two sentences read differently.", "The after-skin refusal advertises the achievable range for acid and for a fracture, and the before-skin refusal does not mention it.", "They do not differ, one sentence being emitted for either skin with the offending value substituted into it."]'::jsonb, 2, 'The before-skin sentence ends that this is the equation running out and not a well. Both fire only where the denominator reaches zero.'),
  ('intervention', 'beginner', 'final', null, 32, 'A claimed uplift of 2.000 times on the published geometry implies a post-job skin of -3.950362292. What can be said about that claim?', '["That it is unreachable, being past the -3 to -5 the module names for acid and past the -5 to -6 it names for a fracture as well.", "That it cannot be assessed without a floor.", "That it is at the floor of that geometry.", "That the implied skin sits inside the range the module''s own text calls achievable on acid."]'::jsonb, 3, 'The floor is -7.900724584 and the text puts acid at about -3 to -5. The inverse says nothing about any of that, so the comparison is one the reader has to make.'),
  ('intervention', 'beginner', 'final', null, 33, 'Which reading prints the note that water is accelerating away from the oil?', '["A channelling reading, whose note calls the climb distinctly steeper than the roughly proportional climb of ordinary displacement.", "A coning reading, whose derivative is falling away from the ratio above it.", "A displacement reading, at a slope of 1.00 and about proportional.", "Any reading inside the ambiguous band, the note being what the band exists to attach."]'::jsonb, 0, 'The published channelling history at the default window returns a derivative slope of 1.600000000 and that note. Water finding a path of its own is the channelling picture.'),
  ('intervention', 'beginner', 'final', null, 34, 'minWor is 0.1 and is applied to which part of a history?', '["Every sample in the late window, a ratio below it anywhere disqualifying the window from being read at all.", "The last sample alone.", "The mean of the late window, which is what the floor is compared against before the derivative is fitted.", "The first sample, since a history that starts below the floor has no water problem to diagnose in the first place."]'::jsonb, 1, 'It is the ratio floor and it sits beside a channellingSlope of 1.3, a coningSlope of -0.1, an ambiguousBand of 0.25, a minR2 of 0.5 and a minSpanDecades of 0.4.'),
  ('intervention', 'beginner', 'final', null, 35, 'The published flat history publishes a late derivative slope of null. Why?', '["Because the golden withholds a slope wherever it publishes no expected mechanism, and the flat history is the one series it leaves unlabelled.", "Because a constant ratio has an undefined derivative.", "Its derivative is 0.000000000 at every sample, so nothing survives to be fitted.", "Because its late window holds fewer than three samples."]'::jsonb, 2, 'Its 40 samples all sit at a ratio of 1.200000000. The derivative fit over the late window returns ok = false on n = 0 and the label that comes back is displacement.'),
  ('intervention', 'beginner', 'final', null, 36, 'What does the coning note give as the answers to a coning well?', '["A shutoff squeeze aimed at the bottom perforations, which is where the cone reaches the wellbore and where it can be isolated.", "A recompletion higher in the interval, which is the treatment the mechanism table promotes to a candidate on a coning reading.", "A production log first, then a squeeze if the log confirms the reading.", "Less drawdown, a different completion, or living with it."]'::jsonb, 3, 'The note says there is nothing to squeeze because the cone re-forms above whatever is shut off, and coning carries treatable = false.'),
  ('intervention', 'beginner', 'final', null, 37, 'Why are the four fit members written at full precision rather than rounded on the way?', '["Because a rounded number cannot be checked by somebody else, and the whole value of the fit is that two independent routes can be compared on it.", "Because the thresholds are quoted to that precision and a comparison against 1.3 needs matching digits.", "Because the fit quality is a fraction and rounding it moves it across the floor of 0.5.", "Because the span in log cycles is sensitive to rounding in a way the slope is not."]'::jsonb, 0, 'The published power law returns 1.350000000000, 1.308332819650, 1.000000000000 and 2.000000000, and its agreement with the independent route is a difference of 0.0000e+0 on the first two.'),
  ('intervention', 'beginner', 'final', null, 38, 'A planner writes a mechanism and a verdict into a recommendation. What has to be said beside them?', '["That the golden publishes a mechanism for each of the four labelled histories, so the classifier has been checked on four series.", "That neither is asserted against anything, the classifier, the screening, the ranking and the inverse skin having no independent check at all.", "That the confidence field is what stands behind them, being the module''s own statement of how much the reading is worth.", "That the fit quality behind the reading cleared the floor of 0.5, which is what licenses a label."]'::jsonb, 1, 'The oracle checks the log-log slope and the skin uplift and stops. The only part of this module that returns a verdict is the part with no golden.'),
  ('intervention', 'beginner', 'final', null, 39, 'Why is the floor computed after the group rather than before it?', '["Because the floor needs the skin, and the skin is the last of the three terms to enter the group.", "Because the floor is only defined once the group has been shown to be positive, a negative group having no floor beneath it.", "It is the same group with the skin removed and the sign flipped, so the group is what it is built from.", "Because the multiplier has to be computed in between the two, the floor being returned inside its result."]'::jsonb, 2, 'On the published geometry the group at zero skin is 7.900724584041 and the floor is -7.900724584041, which is why the two read the same apart from the sign.'),
  ('intervention', 'beginner', 'final', null, 40, 'The measurement refuses loudly in two ways and quietly in one. Which is the quiet one?', '["The refusal on fewer than three usable points, which is quiet because the sentence it prints names the count rather than the points it dropped.", "The refusal on a column where every point sits at the same time, since that one returns no number a reader could mistake for an answer.", "The clamp on the window fraction, which silently replaces a value outside its range rather than refusing it.", "The removal of every point whose y is not strictly positive."]'::jsonb, 3, 'The two loud ones print sentences. The drop prints nothing, and the count it returns is the count after it, which is why comparing n against your own array length is the only warning available.'),
  ('intervention', 'beginner', 'final', null, 41, 'Two published histories return an identical fit quality of 1.000000000 over the same window and receive opposite verdicts. What made the difference?', '["One slope sat above a threshold of 1.3 and the other below it, and that comparison is the entire separation between the two verdicts.", "One fit used more of the window than the other, at 20 samples against the count that survived the positive filter.", "One history is a power law and the other is not, so only one of the two slopes is a real measurement.", "One reading fell inside the ambiguous band and was flagged, and the other did not."]'::jsonb, 0, 'The channelling history returns 1.600000000 and the displacement history 1.000000000, both at a fit quality of 1.000000000 over 20 samples and 1.206802663 log cycles. Neither fit is better than the other.'),
  ('intervention', 'beginner', 'final', null, 42, 'What does a log-log slope carry that lets it be compared against a threshold?', '["A fit quality, which is what makes one slope comparable with another taken on a different well and a different column.", "No unit at all, being a ratio of two logarithms.", "The span it was measured over, which travels in the return and normalises the comparison against the floor of 0.4.", "Its sign, which is the only part of a slope a threshold reads."]'::jsonb, 1, 'The published power law returns 1.350000000000 while its y column runs from 3.700000000 to 1854.392764421. Change what those columns are counted in and the slope does not move, which the intercept does not manage.');
